-- Verkefnasjóður aftur sem sér flipi undir Um HSK, með umsóknarformi
UPDATE pages SET parent_id = (SELECT id FROM pages WHERE path = 'um-hsk'), path = 'um-hsk/verkefnasjodur', in_menu = 1, sort = 40, module = 'grant', status = 'published', body = '<p>Verkefnasjóður HSK var stofnaður á héraðsþingi 26. febrúar 2000. Tilgangur hans er að styrkja félags- og íþróttastarf á sambandssvæði HSK. Sjóðurinn veitir ekki styrki til mannvirkjagerðar; að öðru leyti fer úthlutun eftir mati stjórnar sjóðsins.</p><p><strong>Úthlutað er tvisvar á ári.</strong> Umsóknir þurfa að berast fyrir 1. apríl og 1. október. <a href="#umsokn">Sækja um styrk</a> með forminu neðst á síðunni.</p><p><a href="/um-hsk/log-og-reglugerdir#reglugerd-fyrir-verkefnasjod-hsk">Reglugerð fyrir Verkefnasjóð HSK</a></p><h2>Úthlutanir fyrri ára</h2><ul class="link-list"><li><a href="/media/old/skjol/Uthlutun_Verkefnasjods_HSK_2025.docx">Úthlutanir 2025</a></li><li><a href="/media/old/skjol/Uthlutun_Verkefnasjods-HSK_2024.docx">Úthlutanir 2024</a></li><li><a href="/media/old/skjol/Uthlutun_Verkefnasjods_HSK_2023.doc">Úthlutanir 2023</a></li><li><a href="/media/old/skjol/Verkefnasj_HSK_2022.doc">Úthlutanir 2022</a></li><li><a href="/media/old/skjol/Verkefnasj_HSK_2021.doc">Úthlutanir 2021</a></li><li><a href="/media/old/skjol/Verkefnasj_HSK_2020.doc">Úthlutanir 2020</a></li><li><a href="/media/old/skjol/uthl_2019.doc">Úthlutanir 2019</a></li><li><a href="/media/old/skjol/haust_2018_uthl.xlsx">Úthlutanir 2018, haust</a></li><li><a href="/media/old/skjol/vor_2018_uthl.xlsx">Úthlutanir 2018, vor</a></li><li><a href="/media/old/skjol/haust_2017_uthl.xlsx">Úthlutanir 2017, haust</a></li><li><a href="/media/old/skjol/vor_2017_uthl.xlsx">Úthlutanir 2017, vor</a></li><li><a href="/media/old/skjol/Uthlutun_ur_Verkefnasjodi_HSK_2016.xlsx">Úthlutanir 2016</a></li><li><a href="/media/old/skjol/Uthlutun_ur_Verkefnasjodi_HSK_2015.xlsx">Úthlutanir 2015</a></li><li><a href="/media/old/skjol/Uthlutun_ur_Verkefnasjodi_HSK_2014.xls">Úthlutanir 2014</a></li><li><a href="/media/old/skjol/Uthlutun_ur_Ve